#!/usr/bin/env node

/**
 * Parses the VTT generated by edge-tts into frame-based subtitles for Remotion,
 * and attaches each cue's narration segment (kind: intro | match | outro,
 * plus matchIndex) so the video can time cards to the real TTS cues.
 *
 * Usage: node scripts/parse_vtt.mjs [fps=30]
 */

import fs from 'fs';
import path from 'path';

const fps = parseInt(process.argv[2] || '30');
const vttPath = path.resolve('remotion/public/worlds/narration.vtt');
const outJson = path.resolve('remotion/public/worlds/subtitles.json');
const segmentsPath = path.resolve('remotion/public/worlds/summary.json');

if (!fs.existsSync(vttPath)) {
  console.log('No narration.vtt found, writing empty subtitles.');
  fs.writeFileSync(outJson, '[]');
  process.exit(0);
}

const vttContent = fs.readFileSync(vttPath, 'utf-8');

function timeToFrames(timeStr) {
  // Format: 00:00:01.500 or 00:01.500
  const parts = timeStr.trim().split(':');
  let seconds = 0;
  if (parts.length === 3) {
    seconds = parseFloat(parts[0]) * 3600 + parseFloat(parts[1]) * 60 + parseFloat(parts[2]);
  } else if (parts.length === 2) {
    seconds = parseFloat(parts[0]) * 60 + parseFloat(parts[1]);
  }
  return Math.round(seconds * fps);
}

const lines = vttContent.split('\n');
const items = [];

for (let i = 0; i < lines.length; i++) {
  const line = lines[i].trim();
  if (line.includes('-->')) {
    const [startStr, endStr] = line.split('-->');
    const text = lines[i + 1] ? lines[i + 1].trim() : '';
    if (text) {
      items.push({
        start: timeToFrames(startStr),
        end: timeToFrames(endStr),
        text,
      });
    }
  }
}

// Zip cues with the narration segments (same order, 1:1 with lines).
let segments = [];
if (fs.existsSync(segmentsPath)) {
  try {
    segments = JSON.parse(fs.readFileSync(segmentsPath, 'utf-8'));
  } catch (e) {
    console.warn(`Could not parse ${segmentsPath}: ${e.message}`);
  }
}

const sameShape = Array.isArray(segments) && segments.length === items.length;

items.forEach((item, i) => {
  if (sameShape) {
    item.kind = segments[i].kind;
    if (typeof segments[i].matchIndex === 'number') item.matchIndex = segments[i].matchIndex;
    return;
  }
  // Fallback heuristic when counts drift.
  if (/^第\s*\d+\s*场/.test(item.text)) item.kind = 'match';
  else if (item.text.includes('以上是今天') || /感谢观看|下期|再见/.test(item.text)) item.kind = 'outro';
  else if (/今日共|横扫|最长一局|总结/.test(item.text)) item.kind = 'recap';
  else item.kind = 'intro';
});

if (!sameShape && segments.length) {
  console.warn(
    `[parse_vtt] Segment/cue count mismatch (${segments.length} vs ${items.length}); used text heuristic.`
  );
}

fs.writeFileSync(outJson, JSON.stringify(items, null, 2), 'utf-8');
console.log(`Parsed ${items.length} subtitles to ${outJson}`);
